## Handling Conditional Branching

```tsx
// When quiz has conditional logic, total steps can change dynamically
function calculateEstimatedTotal(
  questions: Question[],
  currentPath: string[],
  conditionalRules: ConditionalRule[],
): number {
  // Start from current position, walk the most likely path
  let remaining = 0;
  let currentQuestionId = currentPath[currentPath.length - 1];

  const visited = new Set(currentPath);
  let safetyCounter = 0;
  const maxIterations = questions.length;

  while (currentQuestionId && safetyCounter < maxIterations) {
    safetyCounter++;
    const rule = conditionalRules.find((r) => r.fromQuestionId === currentQuestionId);

    if (rule) {
      // Use default/fallback branch for estimation
      currentQuestionId = rule.defaultNextQuestionId;
    } else {
      // Linear: next question by position
      const currentQ = questions.find((q) => q.id === currentQuestionId);
      if (!currentQ) break;
      const nextQ = questions.find((q) => q.position === currentQ.position + 1);
      currentQuestionId = nextQ?.id ?? '';
    }

    if (currentQuestionId && !visited.has(currentQuestionId)) {
      remaining++;
      visited.add(currentQuestionId);
    } else {
      break;
    }
  }

  return currentPath.length + remaining;
}
```

