## Unified Progress Renderer

```tsx
function QuizProgress({ config }: { config: ProgressConfig }) {
  if (config.type === 'none') return null;

  const { currentStep, estimatedTotalSteps } = useProgress();

  switch (config.type) {
    case 'bar':
      return <LinearProgressBar config={config} />;
    case 'dots':
      return <StepDots config={config} />;
    case 'numbers':
      return (
        <Text variant="bodyMd" alignment="center">
          Question {currentStep + 1} of {estimatedTotalSteps}
        </Text>
      );
    case 'fraction':
      return (
        <Text variant="bodySm" tone="subdued" alignment="center">
          {currentStep + 1}/{estimatedTotalSteps}
        </Text>
      );
    default:
      return null;
  }
}
