  onSelect,
}: {
  variants: ProductVariant[];
  selectedVariant: ProductVariant;
  onSelect: (variant: ProductVariant) => void;
}) {
  // Group options by name (e.g., Color, Size)
  const optionGroups = useMemo(() => {
    const groups = new Map<string, Set<string>>();
    variants.forEach((v) => {
      v.selectedOptions.forEach(({ name, value }) => {
        if (!groups.has(name)) groups.set(name, new Set());
        groups.get(name)!.add(value);
      });
    });
    return groups;
  }, [variants]);

  const [selectedOptions, setSelectedOptions] = useState<Record<string, string>>(
    Object.fromEntries(selectedVariant.selectedOptions.map((o) => [o.name, o.value])),
  );

  function handleOptionChange(optionName: string, value: string) {
    const newOptions = { ...selectedOptions, [optionName]: value };
    setSelectedOptions(newOptions);
    const match = variants.find((v) =>
      v.selectedOptions.every((o) => newOptions[o.name] === o.value),
    );
    if (match) onSelect(match);
  }

  return (
    <div className="qs-variant-selector">
      {Array.from(optionGroups.entries()).map(([name, values]) => (
        <div key={name} className="qs-variant-selector__group">
          <label className="qs-variant-selector__label">{name}</label>
          <select
            value={selectedOptions[name]}
            onChange={(e) => handleOptionChange(name, e.target.value)}
            className="qs-variant-selector__select"
          >
            {Array.from(values).map((value) => (
              <option key={value} value={value}>{value}</option>
            ))}
          </select>
        </div>
      ))}
    </div>
  );
}
