// Storefront — use Fetch API to Storefront Ajax Cart API
async function addToCart(variantId: string, quantity: number = 1): Promise<void> {
  const numericId = variantId.replace('gid://shopify/ProductVariant/', '');
  const response = await fetch('/cart/add.js', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      items: [{ id: parseInt(numericId, 10), quantity }],
    }),
  });
  if (!response.ok) throw new Error('Failed to add to cart');

  // Trigger cart drawer/notification — dispatch custom event
  document.dispatchEvent(new CustomEvent('quizsnap:cart:updated'));
}

// Add all recommended products at once
async function addAllToCart(variantIds: string[]): Promise<void> {
  const items = variantIds.map((id) => ({
    id: parseInt(id.replace('gid://shopify/ProductVariant/', ''), 10),
    quantity: 1,
  }));
  await fetch('/cart/add.js', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ items }),
  });
  document.dispatchEvent(new CustomEvent('quizsnap:cart:updated'));
}
