## Trigger Manager (Storefront Script)

```tsx
class QuizSnapTriggerManager {
  private config: TriggerConfig;
  private quizId: string;
  private hasTriggered = false;

  constructor(quizId: string, config: TriggerConfig) {
    this.quizId = quizId;
    this.config = config;
  }

  initialize(): void {
    if (this.isFrequencyCapped()) return;

    switch (this.config.type) {
      case 'button':
        this.setupButtonTrigger();
        break;
      case 'scroll_depth':
        this.setupScrollTrigger();
        break;
      case 'timer':
        this.setupTimerTrigger();
        break;
      case 'exit_intent':
        this.setupExitIntentTrigger();
        break;
      case 'manual':
        // Exposed via window.QuizSnap.open(quizId)
        break;
    }
  }

  private isFrequencyCapped(): boolean {
    const key = `qs_shown_${this.quizId}`;
    const lastShown = localStorage.getItem(key);
    if (!lastShown) return false;

    const lastShownTime = parseInt(lastShown, 10);
    const now = Date.now();

    switch (this.config.frequencyCap) {
      case 'every_visit':
        return false;
      case 'once_per_session':
        return sessionStorage.getItem(key) === 'true';
      case 'once_per_day':
        return now - lastShownTime < 86_400_000;
      case 'once_per_week':
        return now - lastShownTime < 604_800_000;
      case 'once_ever':
        return true;
      default:
        return false;
    }
  }

  private recordShown(): void {
    const key = `qs_shown_${this.quizId}`;
    localStorage.setItem(key, String(Date.now()));
    sessionStorage.setItem(key, 'true');
  }

  private show(): void {
    if (this.hasTriggered) return;
    this.hasTriggered = true;
    this.recordShown();
    document.dispatchEvent(
      new CustomEvent('quizsnap:open', { detail: { quizId: this.quizId, displayMode: this.config.displayMode } }),
    );
  }

  private setupScrollTrigger(): void {
    const threshold = this.config.scrollDepthPercent ?? 50;
    const handler = () => {
      const scrollPercent = (window.scrollY / (document.body.scrollHeight - window.innerHeight)) * 100;
      if (scrollPercent >= threshold) {
        this.show();
        window.removeEventListener('scroll', handler);
      }
    };
    window.addEventListener('scroll', handler, { passive: true });
  }

  private setupTimerTrigger(): void {
    const delay = (this.config.delaySeconds ?? 5) * 1000;
    setTimeout(() => this.show(), delay);
  }

  private setupExitIntentTrigger(): void {
    // Desktop only — detect mouse leaving viewport at top
    const sensitivityMap = { low: 50, medium: 20, high: 5 };
    const threshold = sensitivityMap[this.config.exitIntentSensitivity ?? 'medium'];

    const handler = (e: MouseEvent) => {
      if (e.clientY <= threshold) {
        this.show();
        document.removeEventListener('mouseout', handler);
      }
    };
    document.addEventListener('mouseout', handler);
  }

  private setupButtonTrigger(): void {
    // Button rendered separately — listens for click event
    document.addEventListener('quizsnap:button-click', () => this.show());
  }
}
