## Popup Overlay Component

```tsx
interface PopupContainerProps {
  quizId: string;
  displayMode: TriggerConfig['displayMode'];
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
}

function PopupContainer({ quizId, displayMode, isOpen, onClose, children }: PopupContainerProps) {
  // Close on Escape key
  useEffect(() => {
    function handleEscape(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose();
    }
    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden'; // Prevent background scroll
    }
    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = '';
    };
  }, [isOpen, onClose]);

  // Trap focus within popup
  const containerRef = useRef<HTMLDivElement>(null);

  if (!isOpen) return null;

  const modeClasses: Record<string, string> = {
    popup: 'qs-popup--center',
    'slide-right': 'qs-popup--slide-right',
    'slide-bottom': 'qs-popup--slide-bottom',
    fullscreen: 'qs-popup--fullscreen',
  };

  return (
    <div className="qs-popup-backdrop" onClick={onClose} role="presentation">
      <div
        ref={containerRef}
        className={`qs-popup-container ${modeClasses[displayMode]}`}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="Product recommendation quiz"
      >
        <button
          className="qs-popup-close"
          onClick={onClose}
          aria-label="Close quiz"
          type="button"
        >
          ×
        </button>
        {children}
      </div>
    </div>
  );
}
