import type { LoaderFunctionArgs } from 'react-router';

export async function loader({ params }: LoaderFunctionArgs) {
  const quiz = await prisma.quiz.findUnique({
    where: { id: params.id },
    include: { questions: { include: { answers: true }, orderBy: { position: 'asc' } } },
  });
  return json({ quiz });
}

export default function QuizPreview() {
  const { quiz } = useLoaderData<typeof loader>();
  const [previewState, setPreviewState] = useState<QuizFormState | null>(null);

  // Listen for real-time updates from parent editor
  useEffect(() => {
    function handleMessage(event: MessageEvent) {
      if (event.data?.type === 'quizsnap:preview-update') {
        setPreviewState(event.data.payload);
      }
      if (event.data?.type === 'quizsnap:preview-navigate') {
        setCurrentQuestion(event.data.payload.questionIndex);
      }
    }
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  const activeState = previewState ?? quizToFormState(quiz);

  return (
    <div className="qs-preview-root">
      <QuizRenderer state={activeState} isPreview={true} />
    </div>
  );
}
