```tsx
interface QuizRendererProps {
  state: QuizFormState;
  isPreview: boolean;
  onComplete?: (answers: Record<string, string>) => void;
}

function QuizRenderer({ state, isPreview, onComplete }: QuizRendererProps) {
  const [currentView, setCurrentView] = useState<'welcome' | 'question' | 'loading' | 'results'>('welcome');
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<string, string>>({});

  return (
    <div className="qs-quiz" style={{ '--qs-accent': state.design.accentColor } as React.CSSProperties}>
      {currentView === 'welcome' && (
        <WelcomeScreen config={state.welcome} onStart={() => setCurrentView('question')} />
      )}
      {currentView === 'question' && (
        <>
          <QuizProgress config={state.progressBar} />
          <QuestionView
            question={state.questions[currentQuestionIndex]}
            selectedAnswer={selectedAnswers[state.questions[currentQuestionIndex].id]}
            onAnswer={(answerId) => {
              setSelectedAnswers((prev) => ({
                ...prev,
                [state.questions[currentQuestionIndex].id]: answerId,
              }));
            }}
            onNext={() => {
              if (currentQuestionIndex < state.questions.length - 1) {
                setCurrentQuestionIndex((i) => i + 1);
              } else {
                setCurrentView('loading');
                if (!isPreview) onComplete?.(selectedAnswers);
              }
            }}
            onBack={() => setCurrentQuestionIndex((i) => Math.max(0, i - 1))}
          />
        </>
      )}
      {currentView === 'loading' && (
        <LoadingScreen onDone={() => setCurrentView('results')} />
      )}
      {currentView === 'results' && (
        <ResultsScreen config={state.results} isPreview={isPreview} />
      )}
    </div>
  );
}
```

