## Swipe Navigation for Quiz Questions

```tsx
interface SwipeHandlers {
  onSwipeLeft?: () => void;
  onSwipeRight?: () => void;
}

function useSwipeGesture(ref: React.RefObject<HTMLElement>, handlers: SwipeHandlers) {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    let startX = 0;
    let startY = 0;
    let startTime = 0;

    function handleTouchStart(e: TouchEvent) {
      startX = e.touches[0].clientX;
      startY = e.touches[0].clientY;
      startTime = Date.now();
    }

    function handleTouchEnd(e: TouchEvent) {
      const endX = e.changedTouches[0].clientX;
      const endY = e.changedTouches[0].clientY;
      const diffX = endX - startX;
      const diffY = endY - startY;
      const elapsed = Date.now() - startTime;

      // Minimum swipe: 50px horizontal, less than 100px vertical, within 300ms
      const isHorizontalSwipe = Math.abs(diffX) > 50 && Math.abs(diffY) < 100 && elapsed < 300;

      if (isHorizontalSwipe) {
        if (diffX < 0) handlers.onSwipeLeft?.();
        if (diffX > 0) handlers.onSwipeRight?.();
      }
    }

    el.addEventListener('touchstart', handleTouchStart, { passive: true });
    el.addEventListener('touchend', handleTouchEnd, { passive: true });
    return () => {
      el.removeEventListener('touchstart', handleTouchStart);
      el.removeEventListener('touchend', handleTouchEnd);
    };
  }, [ref, handlers]);
}

// Usage in quiz question navigation
function QuestionView({ question, onNext, onBack }: QuestionViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useSwipeGesture(containerRef, {
    onSwipeLeft: onNext,   // Swipe left = next question
    onSwipeRight: onBack,  // Swipe right = previous question
  });

  return (
    <div ref={containerRef} className="qs-question-container">
      {/* Question content */}
    </div>
  );
}
```

